### Example 1: Basic Key-Value Creation

```python
# Create various dictionaries from scratch

# Number → its square
squares = {n: n**2 for n in range(1, 8)}
print(squares)
# {1: 1, 2: 4, 3: 9, 4: 16, 5: 25, 6: 36, 7: 49}

# Number → whether it's even (bool)
is_even = {n: n % 2 == 0 for n in range(1, 9)}
print(is_even)
# {1: False, 2: True, 3: False, 4: True, 5: False, 6: True, 7: False, 8: True}

# Word → its length
words = ['python', 'java', 'javascript', 'rust', 'go']
word_lengths = {word: len(word) for word in words}
print(word_lengths)
# {'python': 6, 'java': 4, 'javascript': 10, 'rust': 4, 'go': 2}

# Character → ASCII code
chars = 'ABCDE'
char_codes = {c: ord(c) for c in chars}
print(char_codes)
# {'A': 65, 'B': 66, 'C': 67, 'D': 68, 'E': 69}

# Reverse: ASCII code → character
code_chars = {ord(c): c for c in chars}
print(code_chars)
# {65: 'A', 66: 'B', 67: 'C', 68: 'D', 69: 'E'}
```

### Example 2: Transforming Existing Dictionaries

```python
# Apply transformations to values of an existing dictionary

prices = {'apple': 1.20, 'banana': 0.50, 'cherry': 2.50, 'date': 3.00}

# Apply 20% discount to all prices
discounted = {item: round(price * 0.80, 2) for item, price in prices.items()}
print(discounted)
# {'apple': 0.96, 'banana': 0.4, 'cherry': 2.0, 'date': 2.4}

# Format prices as currency strings
formatted = {item: f'${price:.2f}' for item, price in prices.items()}
print(formatted)
# {'apple': '$1.20', 'banana': '$0.50', 'cherry': '$2.50', 'date': '$3.00'}

# Convert all keys to uppercase
upper_keys = {k.upper(): v for k, v in prices.items()}
print(upper_keys)
# {'APPLE': 1.2, 'BANANA': 0.5, 'CHERRY': 2.5, 'DATE': 3.0}

# Round all values to nearest integer
rounded = {k: round(v) for k, v in prices.items()}
print(rounded)
# {'apple': 1, 'banana': 0, 'cherry': 2 (or 3), 'date': 3}
```

### Example 3: Building Lookup Tables

```python
# Lookup tables (index, cache) — one of the most valuable uses!

# Products list → fast ID lookup
products = [
    {'id': 'P001', 'name': 'Laptop',   'price': 999},
    {'id': 'P002', 'name': 'Mouse',    'price': 29},
    {'id': 'P003', 'name': 'Monitor',  'price': 399},
    {'id': 'P004', 'name': 'Keyboard', 'price': 79},
]

# Build O(1) lookup by ID
product_by_id = {p['id']: p for p in products}

# Now lookup is instant:
print(product_by_id['P002'])
# {'id': 'P002', 'name': 'Mouse', 'price': 29}

# Build lookup by name
product_by_name = {p['name'].lower(): p for p in products}
print(product_by_name['laptop']['price'])  # 999

# Build price-only lookup (lighter)
price_lookup = {p['id']: p['price'] for p in products}
print(price_lookup)
# {'P001': 999, 'P002': 29, 'P003': 399, 'P004': 79}

# Why is this valuable?
# Without lookup: O(n) search through list every time
orders = ['P001', 'P003', 'P001', 'P002', 'P004', 'P003']
total = sum(price_lookup[pid] for pid in orders)  # O(1) per lookup!
print(f'Order total: ${total}')  # $2505
```

### Example 4: Word Frequency Counter

```python
# Build frequency dictionaries — extremely common in text processing

text = "the quick brown fox jumps over the lazy dog the fox"
words = text.split()

# Method 1: Dict comprehension with count
word_freq = {word: words.count(word) for word in set(words)}
print(word_freq)
# {'the': 3, 'fox': 2, 'quick': 1, 'brown': 1, ...}

# Method 2: Using built-in (more efficient for large texts)
from collections import Counter
word_freq_v2 = dict(Counter(words))
print(word_freq_v2)  # Same result

# Character frequency
sentence = "hello world"
char_freq = {c: sentence.count(c) for c in set(sentence) if c != ' '}
print(char_freq)
# {'h': 1, 'e': 1, 'l': 3, 'o': 2, 'w': 1, 'r': 1, 'd': 1}

# Word length groups (using set for unique words)
unique_words = list(set(words))
length_to_words = {}
for word in unique_words:
    length = len(word)
    if length not in length_to_words:
        length_to_words[length] = []
    length_to_words[length].append(word)
print(length_to_words)
# {3: ['the', 'fox', 'the'...], 5: ['quick', 'brown', ...], 4: ['over', 'lazy'], ...}
```

### Example 5: Real-World API Data Transformation

```python
# Transform API responses into useful dictionaries

# Simulated API response
api_users = [
    {'user_id': 101, 'username': 'alice_j',  'email': 'alice@co.com',  'role': 'admin',  'active': True},
    {'user_id': 102, 'username': 'bob_s',    'email': 'bob@co.com',    'role': 'user',   'active': True},
    {'user_id': 103, 'username': 'carol_w',  'email': 'carol@co.com',  'role': 'user',   'active': False},
    {'user_id': 104, 'username': 'dave_b',   'email': 'dave@co.com',   'role': 'editor', 'active': True},
    {'user_id': 105, 'username': 'eve_m',    'email': 'eve@co.com',    'role': 'admin',  'active': True},
]

# 1. user_id → full user record
users_by_id = {u['user_id']: u for u in api_users}
print(users_by_id[102]['email'])  # 'bob@co.com'

# 2. username → user_id (for login lookup)
username_to_id = {u['username']: u['user_id'] for u in api_users}
print(username_to_id)
# {'alice_j': 101, 'bob_s': 102, ...}

# 3. user_id → role (permission check)
id_to_role = {u['user_id']: u['role'] for u in api_users}
print(id_to_role[105])  # 'admin'

# 4. email → active status
email_to_active = {u['email']: u['active'] for u in api_users}
print(email_to_active)
# {'alice@co.com': True, 'bob@co.com': True, 'carol@co.com': False, ...}

# 5. Create a sanitized public profile dict (no email)
public_profiles = {
    u['user_id']: {
        'username': u['username'],
        'role':     u['role'],
        'active':   u['active']
    }
    for u in api_users
}
print(public_profiles[101])
# {'username': 'alice_j', 'role': 'admin', 'active': True}
```
